+// Quote-aware CSV parsing for POST /import (RFC 4180 style).
+// Replaces the naive split(',') of src/legacy/csvImport.ts, which breaks on
+// quoted fields like "Müller, Hans". The legacy file stays untouched (vendored).
+import { mapLegacyCarrier } from '../legacy/carrierCodes.ts';
+import type { LegacyRow } from '../legacy/csvImport.ts';
+
+/** Splits CSV text into records of cells. Handles "quoted, fields", "" escapes and newlines inside quotes. */
+export function parseCsvRecords(text: string): string[][] {
+  const records: string[][] = [];
+  let cells: string[] = [];
+  let cell = '';
+  let inQuotes = false;
+
+  const endCell = (): void => {
+    cells.push(cell);
+    cell = '';
+  };
+  const endRecord = (): void => {
+    endCell();
+    // skip blank lines
+    if (!(cells.length === 1 && cells[0].trim() === '')) records.push(cells);
+    cells = [];
+  };
+
+  for (let i = 0; i < text.length; i++) {
+    const ch = text[i];
+    if (inQuotes) {
+      if (ch === '"') {
+        if (text[i + 1] === '"') {
+          cell += '"';
+          i++;
+        } else {
+          inQuotes = false;
+        }
+      } else {
+        cell += ch;
+      }
+    } else if (ch === '"') {
+      inQuotes = true;
+    } else if (ch === ',') {
+      endCell();
+    } else if (ch === '\n' || ch === '\r') {
+      if (ch === '\r' && text[i + 1] === '\n') i++;
+      endRecord();
+    } else {
+      cell += ch;
+    }
+  }
+  if (cell !== '' || cells.length > 0) endRecord();
+  return records;
+}
+
+/** Same row format as parseLegacyCsv, but with proper quote handling. */
+export function parseImportCsv(text: string): LegacyRow[] {
+  const records = parseCsvRecords(text);
+  if (records.length === 0) return [];
+
+  const header = records[0].map((h) => h.trim().toLowerCase());
+  return records.slice(1).map((cells) => {
+    const get = (name: string): string => (cells[header.indexOf(name)] ?? '').trim();
+    const phone = get('phone');
+    return {
+      tracking_number: get('tracking'),
+      carrier: mapLegacyCarrier(get('carrier')),
+      service_level: get('service') || 'standard',
+      recipient: {
+        name: get('name'),
+        street: get('street'),
+        zip: get('zip'),
+        city: get('city'),
+        country: get('country') || 'AT',
+        ...(phone ? { phone } : {}),
+      },
+    };
+  });
+}
